  const cleanName = (n) => (n || "").replace(/\s*[-–]?\s*\(\s*\d+\s*[*x×].*?\)\s*$/i, "").trim() || n;
  const fmtDate = (x) => x ? new Date(x).toLocaleDateString("en-GB") : "—";
