          {activeView === "review-qr" && (
            <EmployeeReviewQR currentUser={currentUser} stores={stores} visibleStoreIds={myVisibleStoreIds} />
          )}
          {activeView === "my-review" && (
            <MyReviewImpact currentUser={currentUser} opsTeam={opsTeam} stores={stores}/>
          )}
