  onAddStoreDepartment, onUpdateStoreDepartment, onArchiveStoreDepartment, onUnarchiveStoreDepartment,
  onAddStoreRole, onUpdateStoreRole, onArchiveStoreRole, onUnarchiveStoreRole,
